import sys

def main():
    input_line = sys.stdin.readline().strip()
    s = list(input_line)
    has_x_flag = False
    for ch in s:
        if ch == 'X':
            has_x_flag = True
            break
    length = len(s)
    total_ways = 0

    for digit in range(10):
        temp_arr = []
        for ch in s:
            if ch == 'X':
                temp_arr.append(str(digit))
            else:
                temp_arr.append(ch)
        if temp_arr[0] == '0':
            continue

        dp_state = [[0] * 25 for _ in range(2)]
        current_state = 1
        dp_state[0][0] = 1

        for j in range(length):
            for k in range(25):
                dp_state[current_state][k] = 0
            low_bound = 0
            high_bound = 9
            if temp_arr[j] != '_':
                low_bound = high_bound = int(temp_arr[j])
            elif j == 0:
                low_bound += 1

            for prev_mod in range(25):
                for digit_val in range(low_bound, high_bound + 1):
                    next_val = (prev_mod * 10 + digit_val) % 25
                    dp_state[current_state][next_val] += dp_state[current_state ^ 1][prev_mod]
            current_state ^= 1

        total_ways += dp_state[current_state ^ 1][0]
        if not has_x_flag:
            break

    if length == 1 and (s[0] == '_' or s[0] == 'X' or s[0] == '0'):
        total_ways += 1

    print(total_ways)

if __name__ == "__main__":
    main()

